-- 국어 「뉴욕제과점」 카드(객관식 42 + 서술형 4)를 넣는다. 기존 카드는 건드리지 않는다.
-- 주의: korean-newyork 덱은 이미 사이트 메뉴에 있어서, 이 SQL을 실행하는 순간 사이트에 바로 보인다. PR을 합치기 직전에 실행한다.
begin;
do $check$ begin
  if exists (select 1 from public.cards where deck_id='korean-newyork') then raise exception 'korean-newyork already has cards; review before applying'; end if;
end $check$;
update public.decks set description='김연수 「뉴욕제과점」: 구절 풀이·어머니·결말의 깨달음.' where id='korean-newyork';
do $verify$ begin
  if (select count(*) from public.cards where deck_id='korean-newyork') <> 46 then raise exception 'korean-newyork card count mismatch'; end if;
end $verify$;
commit;
