insert into public.cards (id, deck_id, kind, topic, badge, question, passage, answer, wrong, criteria, explanation, source_label, source_page, source_slide, source_url, sort) values
  ('korean-newyork-001', 'korean-newyork', 'choice', '갈래와 구성', '작가가 자신의 유년 체험을 바탕으로 쓴 「뉴욕제과점」', '이 작품의 갈래는?', null, '자전적 소설', array['역사 소설', '우화 소설', '풍자 소설'], '{}'::text[], '「뉴욕제과점」은 작가가 뉴욕제과점에서 보낸 유년의 체험을 바탕으로 쓴 자전적 소설이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 0),
  ('korean-newyork-002', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」 · ''나''가 자신이 겪은 일을 직접 이야기한다', '이 작품의 시점은?', null, '1인칭 주인공 시점', array['1인칭 관찰자 시점', '3인칭 관찰자 시점', '전지적 작가 시점'], '{}'::text[], '작품 속 ''나''가 주인공이 되어 자신의 이야기를 직접 들려주므로 1인칭 주인공 시점이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 1),
  ('korean-newyork-003', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」 · 현재의 ''나''가 뉴욕제과점의 지난날을 떠올린다', '작품 전체의 구성 방식은?', null, '역행적 구성', array['순차적 구성', '환몽 구성', '액자식 구성'], '{}'::text[], '현재에서 과거의 추억으로 거슬러 올라가므로 전체는 역행적 구성이다. 그 안의 삽화들은 순차적으로 이어진다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 2),
  ('korean-newyork-004', 'korean-newyork', 'choice', '갈래와 구성', '뉴욕제과점이라는 배경 → 주제 의식', '이 작품에서 배경이 하는 역할은?', null, '주제 의식을 드러냄', array['단순한 무대 장치', '인물 간 갈등을 해소함', '시대를 풍자함'], '{}'::text[], '뉴욕제과점이라는 배경은 추억이 삶을 살아가게 하는 힘이라는 주제 의식으로 이어진다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 3),
  ('korean-newyork-005', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」 · 사라진 제과점과 그곳의 추억', '이 작품의 주제로 가장 알맞은 것은?', null, '추억이 삶을 살게 하는 힘', array['변해 가는 고향 비판', '가난을 이겨 낸 성공담', '세대 간의 갈등'], '{}'::text[], '''나''는 사라진 뉴욕제과점이 남긴 추억의 힘으로 세상을 살아갈 수 있음을 깨닫는다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 4),
  ('korean-newyork-006', 'korean-newyork', 'choice', '구절의 의미', '"이 소설만은 연필로 쓰기로 했다."', '''나''가 연필로 쓰는 까닭은?', null, '정성 들여 고쳐 가며 쓰려고', array['빨리 끝내려고', '남에게 보이지 않으려고', '어머니가 원해서'], '{}'::text[], '연필은 지우고 고치기 쉽다. 이 소설만은 정성을 들여 수정을 거치며 쓰겠다는 뜻이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 5),
  ('korean-newyork-007', 'korean-newyork', 'choice', '구절의 의미', '"물론 인생은 그런 게 아니다."', '이 말에 담긴 뜻은?', null, '인생은 예상대로 흐르지 않음', array['인생은 늘 행복하기만 함', '노력하면 무엇이든 이룸', '고향은 언제나 변하지 않음'], '{}'::text[], '뉴욕제과점이 사라졌다는 사실과 함께, 인생은 항상 예상대로 흘러가지 않는다는 뜻을 담고 있다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 6),
  ('korean-newyork-008', 'korean-newyork', 'choice', '구절의 의미', '"이제는 더 이상 제과점을 하지 않아요."', '''나''가 이 말을 굳이 하는 까닭은?', null, '그 일이 큰일임을 알리려고', array['어머니를 원망하려고', '새 가게를 자랑하려고', '고향을 잊으려고'], '{}'::text[], '''나''에게 제과점이 문을 닫은 것은 큰일이다. 이 일이 큰일임을 상대에게 알려 주기 위해 하는 말이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 7),
  ('korean-newyork-009', 'korean-newyork', 'choice', '구절의 의미', '고향 사람들은 ''나''의 말에서 곧잘 문맥을 놓친다.', '이 장면이 드러내는 것은?', null, '제과점을 보는 시각 차이', array['고향 사람들의 무지', '''나''의 말솜씨 부족', '고향 사투리의 차이'], '{}'::text[], '''나''는 뉴욕제과점에 큰 의미를 부여하지만 다른 사람들은 그것에 관심이 없다. 서로 다르게 바라보는 것이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 8),
  ('korean-newyork-010', 'korean-newyork', 'choice', '구절의 의미', '"나란 존재는 그 거리 … 이루어진 어떤 것이다."', '이 구절에서 뉴욕제과점의 의미는?', null, '''나''의 정체성을 기른 곳', array['어머니의 일터일 뿐인 곳', '어릴 때 떠나고 싶던 곳', '고향 사람들의 쉼터'], '{}'::text[], '''나''는 뉴욕제과점에서의 유년의 기억으로 이루어져 있으며, 뉴욕제과점은 ''나''의 정체성을 기르는 데 큰 영향을 주었다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 9),
  ('korean-newyork-011', 'korean-newyork', 'choice', '구절의 의미', '의식과 정체성을 이루던 곳이 사라진 ''나''', '''나''가 이런 자신을 빗댄 말은?', null, '실향민', array['이방인', '나그네', '망명객'], '{}'::text[], '''나''의 의식과 정체성을 이루던 뉴욕제과점이 사라졌으므로, 고향을 잃은 실향민처럼 느낀다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 10),
  ('korean-newyork-012', 'korean-newyork', 'choice', '구절의 의미', '"… 다시 되돌아볼 기회가 … 다시 걷고 싶다."', '이 구절에 담긴 ''나''의 마음은?', null, '뉴욕제과점에 돌아가고 싶음', array['다가올 죽음이 두려움', '고향을 영영 떠나고 싶음', '어머니를 원망하는 마음'], '{}'::text[], '죽음을 앞두고 삶을 되돌아볼 기회가 온다면 뉴욕제과점이 있던 거리를 다시 걷고 싶다는, 그곳으로 돌아가고 싶은 마음이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 11),
  ('korean-newyork-013', 'korean-newyork', 'choice', '구절의 의미', '"다른 고향 사람들의 생각이 좀 야속하다."', '이 말에서 드러나는 ''나''의 마음은?', null, '제과점을 향한 애틋함', array['고향 사람들을 향한 분노', '고향을 떠난 후회', '어머니에 대한 미안함'], '{}'::text[], '제과점에 관심 없는 고향 사람들이 야속하게 느껴질 만큼 ''나''는 뉴욕제과점을 애틋하게 여긴다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 12),
  ('korean-newyork-014', 'korean-newyork', 'choice', '구절의 의미', '"정상적인 세상에서 정상적 … 정상적인 일이다."', '''정상적''을 되풀이한 효과는?', null, '반어적으로 상실감 강조', array['사라짐을 기쁘게 받아들임', '세상의 질서를 찬양함', '고향 사람들을 비판함'], '{}'::text[], '''정상적''을 네 번 되풀이하며 먼저 생긴 것이 먼저 없어지는 것은 당연하다고 말하지만, 이는 반어적 표현으로 뉴욕제과점이 사라진 상실감을 강조한다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 13),
  ('korean-newyork-015', 'korean-newyork', 'choice', '구절의 의미', '"정상적인 일이다. 그러니까 … 그와 마찬가지다."', '이 구절에 쓰인 주된 표현법은?', null, '반어법', array['직유법', '설의법', '의인법'], '{}'::text[], '먼저 생긴 것이 먼저 없어지는 것이 정상이라고 말하지만 속뜻은 상실의 아픔이다. 겉말과 속뜻이 반대인 반어법이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 14),
  ('korean-newyork-016', 'korean-newyork', 'choice', '구절의 의미', '"그거보다는 내가 더 많이 팔았지."', '이 말에 드러난 어머니의 마음은?', null, '제과점에 대한 자부심', array['장사에 대한 후회', '아들에 대한 원망', '손님에 대한 불만'], '{}'::text[], '어머니는 뉴욕제과점을 꾸려 온 일에 자부심을 가지고 있다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 15),
  ('korean-newyork-017', 'korean-newyork', 'choice', '구절의 의미', '"훌륭한 것은 대학 등록금이 아니라 그 웃음 …"', '''나''가 더 고맙게 여긴 것은?', null, '어머니의 긍정적인 성격', array['등록금을 마련해 준 일', '빵을 팔아 번 돈', '제과점의 오랜 역사'], '{}'::text[], '''나''는 등록금을 마련해 준 것보다 어머니가 긍정적이고 낙천적인 성격이 된 것을 더 좋아하고 고맙게 여긴다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 16),
  ('korean-newyork-018', 'korean-newyork', 'choice', '구절의 의미', '불빛, 사탕', '이 소재들이 ''나''에게 뜻하는 것은?', null, '힘들 때 떠올리는 추억', array['애써 잊고 싶은 과거', '어머니가 겪은 고생', '고향이 겪은 가난'], '{}'::text[], '불빛과 사탕은 뉴욕제과점의 추억이다. ''나''는 힘들고 헤어질 때마다 이 추억을 떠올린다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 17),
  ('korean-newyork-019', 'korean-newyork', 'choice', '구절의 의미', '"상식적으로 받아들일 수 있었다."', '이 말에 드러난 ''나''의 태도는?', null, '담담히 받아들임', array['분노하며 거부함', '모른 척 외면함', '기뻐하며 반김'], '{}'::text[], '뉴욕제과점이 사라진 일을 상식적으로, 곧 담담하게 받아들일 수 있었다는 뜻이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 18),
  ('korean-newyork-020', 'korean-newyork', 'choice', '구절의 의미', '"고개를 숙이고 … 없었다."', '이 장면에서 ''나''의 마음은?', null, '울컥함', array['홀가분함', '무관심함', '통쾌함'], '{}'::text[], '고개를 숙일 수밖에 없을 만큼 감정이 북받쳐 울컥한 마음을 드러낸다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 19),
  ('korean-newyork-021', 'korean-newyork', 'choice', '구절의 의미', '"둥글게 아롱져 보였다."', '이 표현이 나타내는 것은?', null, '눈물이 차오름', array['안개가 낌', '불빛이 밝아짐', '잠이 쏟아짐'], '{}'::text[], '눈물이 차올라 사물이 둥글게 아롱져 보이는 것이다. 슬픔을 직접 말하지 않고 보이는 모습으로 드러낸다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 20),
  ('korean-newyork-022', 'korean-newyork', 'choice', '구절의 의미', '"세상은 살아 … 된다. 어차피 … 아니겠는가."', '이 구절의 의미는?', null, '추억을 힘 삼아 살아감', array['세상을 포기함', '과거로 돌아가려 함', '고향을 떠나려 함'], '{}'::text[], '소중한 추억의 힘을 세상을 살아가는 원동력으로 삼아 살아가겠다는 뜻이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 21),
  ('korean-newyork-023', 'korean-newyork', 'choice', '구절의 의미', '"나도 누군가에게 내가 없어진 … 알게 됐다."', '''나''가 알게 된 것은?', null, '없어져도 누군가의 힘이 됨', array['혼자서는 살 수 없음', '결국 모두 잊힘', '고향은 변하지 않음'], '{}'::text[], '이별하더라도 남아 있으며, 내가 없더라도 누군가에게 소중한 존재로서 살아갈 힘을 줄 수 있음을 알게 되었다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 22),
  ('korean-newyork-024', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 제과점을 꾸려 삼남매를 길러 낸 어머니', '이 행동에서 드러나는 성격은?', null, '억척스럽고 책임감 강함', array['소심하고 겁이 많음', '허영심이 강함', '무심하고 냉정함'], '{}'::text[], '어머니는 제과점을 경영해 삼남매를 길러 냈다. 억척스럽고 책임감이 강한 인물이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 23),
  ('korean-newyork-025', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 수술 후 사소한 일에도 웃는 어머니', '이 모습에서 드러나는 성격은?', null, '긍정적이고 낙천적임', array['억척스럽고 고집셈', '자존심이 강함', '소극적이고 비관적임'], '{}'::text[], '수술 뒤에도 사소한 일에 웃는 모습에서 긍정적이고 낙천적인 성격을 알 수 있다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 24),
  ('korean-newyork-026', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 등록금까지만 대고 졸업 후엔 돈을 주지 않음', '어머니가 중요하게 여긴 것은?', null, '자립심', array['체면', '학벌', '저축'], '{}'::text[], '어머니는 ''나''에게 대학 등록금까지만 지원하고 졸업 후에는 돈을 주지 않았다. 자립심을 중요하게 여긴 것이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 25),
  ('korean-newyork-027', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 버리는 빵을 검정 봉투에 가리는 어머니', '이 행동에서 드러나는 성격은?', null, '자존심이 강함', array['낭비가 심함', '손님을 속이려 함', '위생에 철저함'], '{}'::text[], '팔지 못해 버리는 빵을 남이 보지 않게 검정 봉투에 가린다. 자존심이 강한 성격이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 26),
  ('korean-newyork-028', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 장사가 안 돼도 가게를 오래 버틴 어머니', '이 행동에서 드러나는 성격은?', null, '소중한 것에 애착이 강함', array['고집이 세고 무책임함', '돈 욕심이 많음', '변화를 즐김'], '{}'::text[], '장사가 안 되어도 오래 버틴 것은 소중히 여기는 것에 대한 애착이 강하기 때문이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 27),
  ('korean-newyork-029', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 버리는 빵을 가림 A / 등록금까지만 지원 B', 'A, B에서 드러나는 성격은? A–B는?', null, '자존심–자립심 중시', array['자립심 중시–자존심', '책임감–낙천성', '애착–자존심'], '{}'::text[], '버리는 빵을 가리는 데서는 강한 자존심이, 등록금까지만 지원한 데서는 자립심을 중시하는 태도가 드러난다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 28),
  ('korean-newyork-030', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」의 어머니', '어머니의 성격으로 알맞지 않은 것은?', null, '소극적이고 비관적임', array['억척스럽고 책임감 강함', '긍정적이고 낙천적임', '자존심이 강함'], '{}'::text[], '어머니는 억척스럽고 책임감이 강하며, 긍정적·낙천적이고 자존심이 강하다. 소극적이고 비관적인 인물이 아니다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 29),
  ('korean-newyork-031', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · 뉴욕제과점의 전성기와 쇠퇴기', '이것과 겹쳐지는 것은?', null, '어머니 삶의 흐름', array['고향 마을의 역사', '''나''의 학창 시절', '아버지의 사업'], '{}'::text[], '뉴욕제과점의 전성기와 쇠퇴기는 어머니 삶의 흐름과 겹쳐진다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 30),
  ('korean-newyork-032', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · ''나''에게 돈과 소중한 추억을 준 제과점', '뉴욕제과점이 형상화된 방식은?', null, '어머니의 분신처럼', array['''나''의 꿈처럼', '고향 사람들처럼', '도시 문명처럼'], '{}'::text[], '뉴욕제과점은 ''나''가 살아가는 데 필요한 돈과 소중한 추억까지 제공했다. 어머니의 분신처럼 형상화된다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 31),
  ('korean-newyork-033', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · 뉴욕제과점이 ''나''에게 준 것', '이에 해당하지 않는 것은?', null, '고향을 떠날 이유', array['살아가는 데 필요한 돈', '소중한 추억', '정체성의 바탕'], '{}'::text[], '뉴욕제과점은 ''나''에게 살아가는 데 필요한 돈과 소중한 추억을 주었고, ''나''의 정체성을 기르는 데 큰 영향을 주었다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 32),
  ('korean-newyork-034', 'korean-newyork', 'choice', '''나''와 고향 사람들', '「뉴욕제과점」 · 뉴욕제과점이 문을 닫았다', '''나'' A, 고향 사람들 B의 반응은? A–B는?', null, '놀람·큰일–무관심', array['무관심–놀람·큰일', '놀람·큰일–슬픔', '안도–무관심'], '{}'::text[], '''나''는 놀라며 큰일로 여기지만, 고향 사람들에게는 소중한 곳이 아니어서 관심이 없다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 33),
  ('korean-newyork-035', 'korean-newyork', 'choice', '''나''와 고향 사람들', '「뉴욕제과점」 · 같은 일에 엇갈린 ''나''와 고향 사람들', '반응이 엇갈린 까닭은?', null, '소중한 추억이 있는지', array['고향에 사는지', '나이가 같은지', '빵을 좋아하는지'], '{}'::text[], '''나''에게 뉴욕제과점은 소중한 추억이 깃든 곳이지만, 고향 사람들에게는 그렇지 않기 때문이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 34),
  ('korean-newyork-036', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · ''나''가 생각하는 앞으로의 세상', '''나''의 생각으로 알맞은 것은?', null, '괴로운 일만 남은 건 아님', array['괴로운 일만 남아 있음', '즐거운 일만 남아 있음', '과거와 똑같이 흘러감'], '{}'::text[], '''나''는 앞으로 살 세상에 괴로운 일이 있겠지만, 괴로운 일만 남은 것은 아니라고 생각한다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 35),
  ('korean-newyork-037', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 추억으로 살아가는 자신을 본 ''나''', '''나''가 깨달은 것은?', null, '없는 것이 나를 살게 함', array['보이는 것이 전부임', '시간이 모든 걸 지움', '추억은 짐이 됨'], '{}'::text[], '뉴욕제과점이 만들어 준 추억으로 살아가는 자신을 보며, 존재하지 않는 무언가가 자신을 살아가게 한다는 것을 깨닫는다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 36),
  ('korean-newyork-038', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 사라진 제과점이 준 깨달음', '깨달음으로 옳지 않은 것은?', null, '보이는 것만이 전부임', array['사라진 것도 내 안에 있음', '삶에서 시간은 의미 없음', '없는 것이 나를 살게 함'], '{}'::text[], '삶에서 시간은 의미가 없고, 보이는 것만이 전부가 아니며, 사라졌다고 생각한 것이 내 안에 존재한다는 것이 ''나''의 깨달음이다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 37),
  ('korean-newyork-039', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 소중한 것들이 떠나 버릴 앞날', '이때 ''나''가 느낀 감정은?', null, '두려움', array['안도감', '희망', '통쾌함'], '{}'::text[], '앞으로 자신의 소중한 것들이 떠나 버릴 것이기에 ''나''는 두려움을 느낀다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 38),
  ('korean-newyork-040', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 어른이 되는 동안 제과점이 있었다는 것', '이것이 ''나''에게 준 마음은?', null, '안도감과 희망', array['두려움과 불안', '상실의 분노', '죄책감'], '{}'::text[], '''나''가 어른이 되는 동안 뉴욕제과점이 있었다는 것이 큰 도움이 되었다는 생각에서 안도감과 희망을 얻는다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 39),
  ('korean-newyork-041', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · ''나''의 마음 변화', '변화의 순서로 알맞은 것은?', null, '두려움→안도·희망→깨달음', array['안도→두려움→깨달음', '깨달음→두려움→안도', '희망→체념→두려움'], '{}'::text[], '소중한 것들이 떠나리라는 두려움에서, 뉴욕제과점이 있었다는 데서 오는 안도감과 희망을 거쳐, 자신도 누군가에게 위안이 되리라는 깨달음에 이른다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 40),
  ('korean-newyork-042', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · "내가 없어져도 누군가에게 오래 …"', '''나''가 바라는 자신의 모습은?', null, '오래 위안이 되는 사람', array['고향에 돌아가는 사람', '제과점을 잇는 사람', '모든 걸 잊는 사람'], '{}'::text[], '''나''는 자신도 없어진 뒤에 누군가에게 오래 위안이 되는 사람으로 남으리라고 생각한다.', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 41),
  ('korean-newyork-written-001', 'korean-newyork', 'written', '어머니와 뉴욕제과점', null, '「뉴욕제과점」에서 뉴욕제과점이 어머니의 분신처럼 형상화되었다고 볼 수 있는 까닭을 두 가지 쓰시오.', null, '뉴욕제과점의 전성기와 쇠퇴기가 어머니 삶의 흐름과 겹쳐진다. 또 뉴욕제과점은 어머니처럼 ''나''가 살아가는 데 필요한 돈과 소중한 추억까지 ''나''에게 주었다. 그래서 뉴욕제과점은 어머니의 분신처럼 형상화된다.', '{}'::text[], array['제과점의 전성기·쇠퇴기 = 어머니 삶의 흐름', '''나''에게 돈과 소중한 추억을 줌', '어머니의 분신으로 형상화됨을 밝힘'], '', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 1000),
  ('korean-newyork-written-002', 'korean-newyork', 'written', '구절의 의미', null, '「뉴욕제과점」에서 ''나''가 "정상적인 세상에서 … 정상적인 일이다"처럼 ''정상적''을 되풀이한 표현의 효과를 쓰시오.', null, '''정상적''을 네 번 되풀이하며 먼저 생긴 것이 먼저 없어지는 것은 당연한 일이라고 말한다. 그러나 이는 겉말과 속뜻이 다른 반어적 표현으로, 뉴욕제과점이 사라진 데서 오는 상실감을 오히려 강조한다.', '{}'::text[], array['''정상적''의 반복 · 먼저 생긴 것이 먼저 없어짐', '반어적 표현임', '뉴욕제과점이 사라진 상실감 강조'], '', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 1001),
  ('korean-newyork-written-003', 'korean-newyork', 'written', '''나''와 고향 사람들', null, '「뉴욕제과점」이 문을 닫은 일에 대한 ''나''와 고향 사람들의 반응을 비교하고, 반응이 다른 까닭을 쓰시오.', null, '''나''는 뉴욕제과점이 문을 닫은 일에 놀라며 큰일로 여기지만, 고향 사람들은 관심이 없다. ''나''에게 뉴욕제과점은 유년의 소중한 추억이 깃들고 정체성을 기른 곳이지만, 고향 사람들에게는 소중한 곳이 아니기 때문이다.', '{}'::text[], array['''나'': 놀람, 큰일로 여김', '고향 사람들: 관심 없음', '''나''에게만 소중한 추억·정체성의 장소'], '', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 1002),
  ('korean-newyork-written-004', 'korean-newyork', 'written', '결말과 깨달음', null, '「뉴욕제과점」 결말에서 ''나''의 마음이 어떻게 바뀌는지 순서대로 쓰고, ''나''가 마지막에 깨달은 것을 쓰시오.', null, '''나''는 앞으로 소중한 것들이 떠나 버릴 것이기에 두려움을 느낀다. 그러나 어른이 되는 동안 뉴욕제과점이 있었다는 것이 큰 도움이 되었음을 떠올리며 안도감과 희망을 얻는다. 마침내 자신도 없어진 뒤에 누군가에게 오래 위안이 되는 사람으로 남으리라는 것을 깨닫는다.', '{}'::text[], array['두려움: 소중한 것들이 떠나 버릴 것', '안도감·희망: 뉴욕제과점이 있었다는 것이 도움이 됨', '깨달음: 나도 누군가에게 오래 위안이 되는 사람으로 남음'], '', '국어 학습 노트 · 김연수 「뉴욕제과점」', null, null, null, 1003);
